/** form-code-field + client search CI / không dấu */
export const normalizeCode = (v: string) => v.trim().toUpperCase();

export const normalizeSearchText = (value?: string): string => {
  if (!value) return '';
  return value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
};

export function matchesCodeOrName(code: string, name: string, query: string, extra?: string): boolean {
  const q = normalizeSearchText(query);
  if (!q) return true;
  return (
    normalizeSearchText(code).includes(q)
    || normalizeSearchText(name).includes(q)
    || normalizeSearchText(extra).includes(q)
  );
}
